SELECT *
  FROM (
    SELECT INNER_LIST.*, ROWNUM AS RNUM
      FROM (
        SELECT * FROM BOOK 

         WHERE BAGE LIKE '%' || #{bage} || '%'

         ORDER BY BNO ASC
      ) INNER_LIST
  )
 WHERE RNUM BETWEEN #{startRow} AND #{endRow}

SELECT *
  FROM (
    SELECT INNER_LIST.*, ROWNUM AS RNUM
      FROM (
        SELECT * FROM BOOK 

         WHERE BGENRE LIKE '%' || #{bgenre} || '%'

         ORDER BY BNO ASC
      ) INNER_LIST
  )
 WHERE RNUM BETWEEN #{startRow} AND #{endRow}

